const countersByDepartmentAndCategory = new Map();

export const anecdotesBatch008 = rawEntries.map(([
  code_departement,
  categorie,
  titre,
  contenu,
  difficulte,
  rarete,
  ton,
  source,
  theme,
]) => {
  const categoryKey = CATEGORY_ID[categorie] ?? categorie;
  const counterKey = `${code_departement}-${categoryKey}`;
  const nextIndex = (countersByDepartmentAndCategory.get(counterKey) ?? 0) + 1;
  countersByDepartmentAndCategory.set(counterKey, nextIndex);

  return {
    id: `${code_departement}-${categoryKey}-${String(nextIndex).padStart(3, "0")}`,
    code_departement,
    titre,
    contenu,
    categorie,
    difficulte,
    rarete,
    ton,
    contexte: CONTEXT,
    source,
    statut_validation: STATUS,
    theme,
    date_ajout: DATE,
    date_modification: DATE,
  };
});
